private Map<String, Set<String>> routeTable() {
    Map<String, Set<String>> table = new LinkedHashMap<>();
    for (Map.Entry<RequestMappingInfo, HandlerMethod> e : mapping().getHandlerMethods().entrySet()) {
        RequestMappingInfo info = e.getKey();
        HandlerMethod hm = e.getValue();
        Set<String> methods = info.getMethodsCondition().getMethods().isEmpty()
            ? Set.of("GET","POST","PUT","DELETE","PATCH","HEAD","OPTIONS")
            : info.getMethodsCondition().getMethods().stream().map(Enum::name).collect(toSet());
        for (String pattern : patterns(info)) {
            String norm = normalize(pattern);
            for (String m : methods) {
                table.computeIfAbsent(m + " " + norm, k -> new LinkedHashSet<>())
                     .add(hm.getBeanType().getSimpleName());
            }
        }
    }
    return table;
}

private static Set<String> patterns(RequestMappingInfo info) {
    Set<String> out = new LinkedHashSet<>();
    if (info.getPathPatternsCondition() != null) {
        for (PathPattern p : info.getPathPatternsCondition().getPatterns()) out.add(p.getPatternString());
    }
    if (info.getPatternCondition() != null) out.addAll(info.getPatternCondition().getPatterns());
    return out;
}

private static String normalize(String path) {
    return path.replaceAll("\\{[^/]*\\}", "{}");
}
