#!/usr/bin/env python3
"""独立校验 springdoc 生成的 /v3/api-docs 是否覆盖契约声明的 27 个业务 API。

用法: verify_swagger27.py <api-docs.json> [expected.tsv]

期望集合默认取 /tmp/opencode/b-swagger-expected.tsv（由 orchestrator 从
backend/contracts/openapi/openapi.yaml 的 x-api-id 独立提取，非实施道自报）。
退出码: 0 = 27/27 全覆盖; 1 = 有缺失; 2 = 输入不可用。
额外路径(非 27 之列)只报告不判失败——不得为凑数隐藏真实端点。
"""
import json
import sys

HTTP = {"get", "post", "put", "delete", "patch"}


def norm(p: str) -> str:
    """归一化路径模板：变量名由各 controller 自定，统一为 {} 后比较。"""
    out, depth = [], 0
    for ch in p:
        if ch == "{":
            depth += 1
            if depth == 1:
                out.append("{}")
        elif ch == "}":
            depth = max(0, depth - 1)
        elif depth == 0:
            out.append(ch)
    s = "".join(out)
    return s[:-1] if len(s) > 1 and s.endswith("/") else s


def main() -> int:
    if len(sys.argv) < 2:
        print(__doc__)
        return 2
    docs_path = sys.argv[1]
    exp_path = sys.argv[2] if len(sys.argv) > 2 else "/tmp/opencode/b-swagger-expected.tsv"

    try:
        with open(docs_path, encoding="utf-8") as f:
            docs = json.load(f)
    except Exception as exc:
        print(f"ERROR: cannot read api-docs JSON {docs_path}: {exc}")
        return 2
    try:
        expected = []
        with open(exp_path, encoding="utf-8") as f:
            for line in f:
                line = line.rstrip("\n")
                if not line or line.startswith("#"):
                    continue
                parts = line.split("\t")
                if len(parts) >= 3:
                    expected.append((parts[0], parts[1].lower(), norm(parts[2])))
    except Exception as exc:
        print(f"ERROR: cannot read expected set {exp_path}: {exc}")
        return 2

    if "paths" not in docs:
        print("ERROR: generated doc has no 'paths' (not a real OpenAPI document?)")
        return 2

    actual = set()
    for path, item in docs["paths"].items():
        if not isinstance(item, dict):
            continue
        for method in item:
            if method.lower() in HTTP:
                actual.add((method.lower(), norm(path)))

    exp_set = {(m, p) for _, m, p in expected}
    missing = sorted(exp_set - actual)
    hit = sorted(exp_set & actual)
    extra = sorted(actual - exp_set)

    print(f"openapi version : {docs.get('openapi')}")
    print(f"info.title      : {docs.get('info', {}).get('title')}")
    print(f"expected (契约)  : {len(exp_set)}")
    print(f"hit             : {len(hit)}/{len(exp_set)}")
    print(f"actual total    : {len(actual)} (含非业务端点)")
    if missing:
        print("\nMISSING (业务 API 未在生成文档中出现):")
        for m, p in missing:
            ids = [a for a, mm, pp in expected if mm == m and pp == p]
            print(f"  - {m.upper()} {p}   [{','.join(ids)}]")
    if extra:
        print("\nEXTRA (生成文档中的其他真实端点，仅报告不判失败):")
        for m, p in extra:
            print(f"  + {m.upper()} {p}")
    sec = docs.get("components", {}).get("securitySchemes", {})
    print(f"\nsecuritySchemes : {sorted(sec)} -> "
          f"{[sec[k].get('type') for k in sorted(sec)]}")
    print(f"global security : {docs.get('security')}")
    print("\nRESULT:", "PASS 27/27" if not missing else f"FAIL missing={len(missing)}")
    return 0 if not missing else 1


if __name__ == "__main__":
    sys.exit(main())

