package cn.yuanxin.mvp.web.state;

import org.springframework.boot.context.properties.ConfigurationProperties;

import java.util.Locale;

/**
 * 会话与阿里云短信状态的存储后端配置（{@code app.state.*}）。
 *
 * <p><b>为什么只有一个开关</b>：会话（access/refresh）与短信状态（challenge、一次性核销、
 * 尝试计数、限流）都需要<b>跨实例一致</b>与<b>重启不丢</b>，不存在"只迁其中一个"的合理场景；
 * 两个开关只会制造半迁移的中间态（本项目已多次吃过"半成功危害"的亏）。</p>
 *
 * <p><b>取值</b>：</p>
 * <ul>
 *   <li>{@code memory}（默认）：现有进程内实现，<b>仅供隔离测试与 doubles</b>；
 *       应用重启即失效、多实例之间不共享；</li>
 *   <li>{@code redis}：跨实例一致的真实实现，联调与真实 provider 必须用它。</li>
 * </ul>
 *
 * <p><b>连接参数一律用 Spring Boot 标准 {@code spring.data.redis.*}</b>
 * （{@code host}/{@code port}/{@code password}/{@code database}/{@code timeout}/
 * {@code connect-timeout}/{@code url}），本类型<b>不</b>重复声明它们，也不做任何 fallback：
 * {@code spring.data.redis.url} 若设置会覆盖 host/port/username/password/database（Boot 语义）。</p>
 *
 * <p><b>fail fast</b>：非法 {@code provider} 取值在绑定期即抛
 * {@link IllegalArgumentException}（消息只含键名与被拒取值，不含任何凭据）；
 * {@link StateStoreConfigGuard} 另在启动早期做同样校验，避免非法值退化成
 * "两个 provider 都不装配 ⇒ 缺 bean"的难诊断错误。</p>
 *
 * <p><b>安全</b>：本类型不含任何凭据字段（Redis 口令由 Boot 的
 * {@code spring.data.redis.password} 承载，绝不在此重复声明），故无需脱敏 {@code toString()}；
 * {@code key-prefix} 是命名空间而非秘密。</p>
 */
@ConfigurationProperties(prefix = "app.state")
public record AppStateProperties(String provider, Redis redis) {

    /** 配置键名（用于装配条件与守卫消息，集中在此避免拼写漂移）。 */
    public static final String PROVIDER_KEY = "app.state.provider";
    public static final String KEY_PREFIX_KEY = "app.state.redis.key-prefix";

    public static final String PROVIDER_MEMORY = "memory";
    public static final String PROVIDER_REDIS = "redis";

    public AppStateProperties {
        provider = normalizeProvider(provider);
        redis = redis == null ? new Redis(null) : redis;
    }

    /**
     * 归一化 provider：null/空白 → {@link #PROVIDER_MEMORY}；否则 trim + 小写后必须是
     * {@code memory} 或 {@code redis}，<b>不接受任何其它值、不做猜测、不做 fallback</b>。
     */
    public static String normalizeProvider(String raw) {
        if (raw == null || raw.isBlank()) {
            return PROVIDER_MEMORY;
        }
        String value = raw.trim().toLowerCase(Locale.ROOT);
        if (!PROVIDER_MEMORY.equals(value) && !PROVIDER_REDIS.equals(value)) {
            throw new IllegalArgumentException("invalid " + PROVIDER_KEY + "=" + raw.trim()
                    + "; expected one of [" + PROVIDER_MEMORY + ", " + PROVIDER_REDIS + "]"
                    + " (no fallback: an unknown backend is never silently treated as memory)");
        }
        return value;
    }

    /** 是否使用 Redis 后端。 */
    public boolean redisEnabled() {
        return PROVIDER_REDIS.equals(provider);
    }

    /**
     * {@code app.state.redis.*}。
     *
     * @param keyPrefix 所有键的命名空间前缀；null/空白 → {@link StateKeys#DEFAULT_PREFIX}。
     *                  测试应使用<b>独立随机前缀</b>隔离，清理时只删自己的前缀（绝不 FLUSHDB）。
     */
    public record Redis(String keyPrefix) {
        public Redis {
            keyPrefix = StateKeys.normalizePrefix(keyPrefix);
        }
    }
}

package cn.yuanxin.mvp.web.state;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;

/**
 * 状态后端的<b>键模型</b>（唯一权威）。所有 Redis 键都必须经本类构造，禁止在业务代码里手拼字符串，
 * 以免键形状漂移导致"旧键读不到"或"清理漏删"。
 *
 * <p><b>键通则</b>：</p>
 * <ol>
 *   <li>形状 = {@code <prefix><域>:<用途>:<标识>}；</li>
 *   <li><b>凭据与 PII 一律以 sha256 十六进制摘要入键</b>（access/refresh token、手机号）。
 *       原因：键会出现在 {@code SCAN}、慢日志、监控与运维排障输出里，原文 token 一旦入键
 *       就等于把持有者凭据散布到可观测面；</li>
 *   <li><b>每个键只用一种 Redis 类型</b>。实测：对 list 做 {@code GET} → {@code WRONGTYPE}；
 *       对非整数字符串做 {@code INCR} → {@code ERR value is not an integer or out of range}。
 *       因此键名带明确用途段，绝不复用同名键承载不同类型；</li>
 *   <li>{@code sessionId} <b>不</b>做摘要：它是服务端生成的随机 UUID、不含用户身份，
 *       且要作为 T09 {@code notification_destinations.session_ref} 与 T13
 *       {@code principal_id} 的一部分被业务使用，必须保持原值可返回。</li>
 * </ol>
 *
 * <p><b>验证码摘要</b>：{@link #codeDigest(String, String)} 以 {@code challengeId} 为盐，
 * 因此<b>明文验证码绝不落入 Redis</b>（比现状的内存明文更严格）：即使 Redis 被导出也拿不到
 * 可用验证码，且相同验证码在不同 challenge 下摘要不同，无法建立全局对照表。</p>
 *
 * <p><b>关于常量时间比较</b>：验证码比较发生在 Lua 内、对<b>定长 sha256 摘要</b>做等值判断。
 * 这里不再使用 {@code MessageDigest.isEqual} 是<b>有意且安全</b>的：被比较的值是 256 位摘要而非
 * 6 位明文码，攻击者无法从摘要等值判断的时序反推验证码（需先找到 sha256 原像）；定长摘要也消除了
 * 长度泄漏。把比较移出 Java 是原子性的<b>必要代价</b>——否则"比较"与"核销/计数"会退化成两步，
 * 重新打开并发核销的竞态窗口。</p>
 */
public final class StateKeys {

    /** 默认命名空间前缀（{@code app.state.redis.key-prefix} 未配置时使用）。 */
    public static final String DEFAULT_PREFIX = "mvp:b:";

    /** 前缀长度上限：过长的前缀会无谓放大每个键的内存占用。 */
    public static final int MAX_PREFIX_LENGTH = 64;

    private static final String SESSION_ACCESS = "sess:at:";
    private static final String SESSION_REFRESH = "sess:rt:";
    private static final String SESSION_BY_ID = "sess:sid:";
    private static final String SMS_CHALLENGE = "sms:ch:";
    private static final String SMS_RATE_LIMIT = "sms:rl:";

    private final String prefix;

    public StateKeys(String prefix) {
        this.prefix = normalizePrefix(prefix);
    }

    /** 归一化后的命名空间前缀（保证非空且以 {@code :} 结尾）。 */
    public String prefix() {
        return prefix;
    }

    /**
     * 归一化并校验前缀：null/空白 → {@link #DEFAULT_PREFIX}；trim 后若不以 {@code :} 结尾则补上；
     * 拒绝含空白或 glob 元字符（{@code * ? [ ]}）的前缀——否则会污染 {@link #pattern(String)}
     * 的 {@code SCAN} 匹配语义，导致测试清理误删他人键。
     */
    public static String normalizePrefix(String raw) {
        if (raw == null || raw.isBlank()) {
            return DEFAULT_PREFIX;
        }
        String value = raw.trim();
        if (value.length() > MAX_PREFIX_LENGTH) {
            throw new IllegalArgumentException("invalid " + AppStateProperties.KEY_PREFIX_KEY
                    + ": length must be <= " + MAX_PREFIX_LENGTH + " characters");
        }
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (Character.isWhitespace(c) || c == '*' || c == '?' || c == '[' || c == ']') {
                throw new IllegalArgumentException("invalid " + AppStateProperties.KEY_PREFIX_KEY
                        + ": must not contain whitespace or glob metacharacters (* ? [ ])");
            }
        }
        return value.endsWith(":") ? value : value + ":";
    }

    /**
     * 校验并拼接一个<b>服务端自己生成</b>的标识段（sessionId、challengeId）。
     * 拒绝空白与 glob 元字符，理由同 {@link #normalizePrefix(String)}。
     */
    private static String safeIdentifier(String value, String what) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(what + " must not be blank");
        }
        String trimmed = value.trim();
        for (int i = 0; i < trimmed.length(); i++) {
            char c = trimmed.charAt(i);
            if (Character.isWhitespace(c) || c == '*' || c == '?' || c == '[' || c == ']') {
                throw new IllegalArgumentException(what + " must not contain whitespace"
                        + " or glob metacharacters (* ? [ ])");
            }
        }
        return trimmed;
    }

    /** sha256 十六进制摘要（小写）。用于 token 与手机号入键，绝不使用原文。 */
    public static String sha256Hex(String value) {
        if (value == null) {
            throw new IllegalArgumentException("value to digest must not be null");
        }
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(digest.digest(value.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException e) {
            // SHA-256 是 JVM 规范强制要求的算法；到这里说明运行环境异常，不静默降级。
            throw new IllegalStateException("SHA-256 is unavailable in this JVM", e);
        }
    }

    /**
     * 验证码的存储/比较摘要：{@code sha256(code + "|" + challengeId)}。
     * 以 challengeId 为盐 ⇒ 明文码不落 Redis，且相同码在不同 challenge 下摘要不同。
     */
    public static String codeDigest(String code, String challengeId) {
        if (code == null || code.isBlank()) {
            throw new IllegalArgumentException("code must not be blank");
        }
        return sha256Hex(code + "|" + safeIdentifier(challengeId, "challengeId"));
    }

    /** access token → 会话记录键（hash）。{@code authenticate} 的唯一查询路径。 */
    public String sessionByAccessToken(String accessToken) {
        return prefix + SESSION_ACCESS + sha256Hex(requireToken(accessToken, "accessToken"));
    }

    /** refresh token → sessionId 键（string）。一次性轮换的 CAS 目标。 */
    public String sessionByRefreshToken(String refreshToken) {
        return prefix + SESSION_REFRESH + sha256Hex(requireToken(refreshToken, "refreshToken"));
    }

    /** sessionId → access token 摘要键（string）。轮换/撤销时定位旧 access token。 */
    public String sessionById(String sessionId) {
        return prefix + SESSION_BY_ID + safeIdentifier(sessionId, "sessionId");
    }

    /** challengeId → 验证码挑战键（hash：摘要、手机号、过期时刻、尝试次数）。 */
    public String smsChallenge(String challengeId) {
        return prefix + SMS_CHALLENGE + safeIdentifier(challengeId, "challengeId");
    }

    /**
     * 手机号 + 窗口 + 自然窗口桶 → 限流计数键（string 整数）。
     *
     * @param window 窗口标识（如 {@code m}/{@code h}/{@code d}）
     * @param bucket 按 UTC+8 自然边界格式化的桶名（如 {@code 202609141230}）
     */
    public String smsRateLimit(String phone, String window, String bucket) {
        return prefix + SMS_RATE_LIMIT + sha256Hex(requireToken(phone, "phone"))
                + ":" + safeIdentifier(window, "window") + ":" + safeIdentifier(bucket, "bucket");
    }

    /**
     * 供<b>测试清理</b>使用的 {@code SCAN} 匹配模式：{@code <prefix><domainGlob>}。
     * 只应传入本实例自己的前缀派生模式；<b>绝不</b>用 {@code FLUSHDB}/{@code FLUSHALL}。
     */
    public String pattern(String domainGlob) {
        return prefix + (domainGlob == null ? "*" : domainGlob);
    }

    private static String requireToken(String value, String what) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(what + " must not be blank");
        }
        return value;
    }

    @Override
    public String toString() {
        // 前缀是命名空间而非秘密，但仍不回显完整键（键含摘要，回显无诊断价值）。
        return "StateKeys[prefix=" + prefix + "]";
    }
}

package cn.yuanxin.mvp.web.state;

import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.QueryTimeoutException;
import org.springframework.data.redis.RedisConnectionFailureException;
import org.springframework.data.redis.RedisSystemException;

/**
 * Redis 状态后端故障的<b>唯一</b>翻译点（fail closed）。
 *
 * <p><b>三条硬纪律</b>：</p>
 * <ol>
 *   <li><b>任何后端故障都不得被吞成 {@code Optional.empty()}</b>。那会把"依赖不可用"伪装成
 *       "会话无效 / 验证码错误 / refresh 无效"（401），既掩盖故障又违反 fail-closed；</li>
 *   <li><b>绝不回退内存实现制造伪成功</b>：{@code app.state.provider=redis} 时不存在内存兜底路径；</li>
 *   <li><b>本地 API 误用不是依赖故障</b>：{@code InvalidDataAccessApiUsageException} 等
 *       属代码缺陷，必须原样抛出（由 {@code GlobalExceptionHandler} 落到 500 {@code INTERNAL}），
 *       不得伪装成 503 让运维误判为"Redis 挂了"。</li>
 * </ol>
 *
 * <p><b>为什么统一 503 {@code DEPENDENCY_UNAVAILABLE} 而不用 504 {@code DEPENDENCY_TIMEOUT}</b>：
 * 命令超时在语义上更接近 504，但既有 HTTP 契约（{@code backend/contracts/openapi/openapi.yaml}
 * 的各操作 {@code responses} 与 {@code x-error-codes}）<b>没有</b>声明 504；引入它等于改变对外契约，
 * 而本轮硬要求是"保持全部 HTTP 契约"。同时 {@code BearerAuthFilter} 既有行为就是把 provider 抛出的
 * {@code RuntimeException} 渲染为 503 {@code DEPENDENCY_UNAVAILABLE} 信封，故 503 也是<b>与现状一致</b>
 * 的选择。该取舍如实记录在 {@code backend/handoffs/B-redis-state-migration.md} §6。</p>
 *
 * <p><b>脱敏</b>：返回给客户端的消息是<b>固定文案 + 操作名</b>，绝不包含 Redis 主机、端口、口令、
 * 键名、token、手机号或验证码。服务端日志记 {@code operation} + 异常类名 + 异常消息
 * （Redis 异常消息不含口令：认证失败为 {@code WRONGPASS invalid username-password pair}，
 * 不回显秘密；键名本身已是摘要而非原文）。</p>
 */
public final class RedisFailures {

    private static final Logger log = LoggerFactory.getLogger(RedisFailures.class);

    private RedisFailures() {
    }

    /**
     * 是否为"状态后端不可用"（连接失败 / 命令超时 / 服务端错误如认证失败、READONLY、
     * {@code ERR DB index is out of range}、OOM 拒命令）。
     */
    public static boolean isStoreUnavailable(Throwable throwable) {
        return throwable instanceof RedisConnectionFailureException
                || throwable instanceof QueryTimeoutException
                || throwable instanceof RedisSystemException;
    }

    /**
     * 把状态后端故障翻译成 fail-closed 的 {@link ApiException}（503
     * {@link ErrorCode#DEPENDENCY_UNAVAILABLE}）；<b>非</b>后端故障原样返回，由调用方抛出。
     *
     * <p>消息明确写出"请求未被处理"，避免客户端把 503 误读为"凭据无效"或"操作已成功"。</p>
     *
     * @param operation 内部操作名（如 {@code authenticate}、{@code verify-challenge}）；
     *                  仅用于诊断，不含任何凭据或 PII
     * @param ex        捕获到的运行时异常
     */
    public static RuntimeException failClosed(String operation, RuntimeException ex) {
        if (!isStoreUnavailable(ex)) {
            return ex;
        }
        log.warn("state store unavailable operation={} cause={} detail={}", operation,
                ex.getClass().getName(), ex.getMessage());
        return new ApiException(ErrorCode.DEPENDENCY_UNAVAILABLE,
                "session/verification state store is unavailable; the request was NOT processed"
                        + " and no credential was accepted or consumed (operation=" + operation + ")");
    }

    /**
     * 便捷包装：执行一段状态后端访问，把后端故障翻译成 fail-closed 的 503。
     * 业务判定（验证码错误、会话不存在等）必须以正常返回值表达，<b>不得</b>借异常通道，
     * 以免被本方法误判为后端故障。
     */
    public static <T> T call(String operation, java.util.function.Supplier<T> action) {
        try {
            return action.get();
        } catch (RuntimeException ex) {
            throw failClosed(operation, ex);
        }
    }
}

package cn.yuanxin.mvp.web.state;

import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * Redis 状态后端的装配入口（仅 {@code app.state.provider=redis} 时激活）。
 *
 * <p><b>刻意不自行创建 {@code LettuceConnectionFactory}</b>：连接工厂与
 * {@code StringRedisTemplate} 由 Spring Boot 的 {@code RedisAutoConfiguration} 按标准
 * {@code spring.data.redis.*} 属性自动配置，本项目不重复实现 host/port/password/database/
 * timeout/url/ssl/sentinel/cluster 的映射（重复实现只会漏掉边界情况）。本类只负责：</p>
 * <ol>
 *   <li>把 {@link AppStateProperties} 注册为 bean（供实现类读取键前缀）；</li>
 *   <li>暴露唯一的 {@link StateKeys} bean —— 所有键都必须经它构造。</li>
 * </ol>
 *
 * <p><b>只用 {@code StringRedisTemplate}</b>：自动配置的 {@code RedisTemplate<Object,Object>}
 * 默认使用 JDK 序列化，Lua 脚本里 {@code redis.call('GET', KEYS[1])} 收到的会是二进制而非字符串，
 * 表现为"键找不到"这类极难诊断的故障。实现类必须注入 {@code StringRedisTemplate}。</p>
 *
 * <p><b>启动期不主动连接 Redis</b>：Boot 的 {@code LettuceConnectionFactory} 默认
 * {@code eagerInitialization=false}，因此 Redis 不可达时上下文仍能启动、首个命令才失败 ⇒
 * 请求期 503 fail-closed（见 {@link RedisFailures}）。这是有意的：把"Redis 短暂不可用"
 * 放大成"整个应用起不来"更糟。<b>配置</b>错误则由 {@link StateStoreConfigGuard} 在启动早期
 * 明确拒绝。</p>
 *
 * <p>{@code proxyBeanMethods=false}：本类无需 CGLIB 增强（避免 @Configuration 代理带来的
 * 构造器可见性等历史坑），bean 方法之间不互相调用。</p>
 */
@Configuration(proxyBeanMethods = false)
@ConditionalOnProperty(name = AppStateProperties.PROVIDER_KEY,
        havingValue = AppStateProperties.PROVIDER_REDIS)
@EnableConfigurationProperties(AppStateProperties.class)
public class RedisStateConfig {

    /**
     * 键模型唯一入口。前缀来自 {@code app.state.redis.key-prefix}
     * （默认 {@link StateKeys#DEFAULT_PREFIX}）；测试应注入<b>独立随机前缀</b>以隔离，
     * 清理时只删自己的前缀。
     */
    @Bean
    public StateKeys stateKeys(AppStateProperties properties) {
        return new StateKeys(properties.redis().keyPrefix());
    }
}

package cn.yuanxin.mvp.web.state;

import cn.yuanxin.mvp.web.config.AppProperties;
import cn.yuanxin.mvp.web.config.NonProductionCondition;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.BeansException;
import org.springframework.beans.factory.config.BeanFactoryPostProcessor;
import org.springframework.beans.factory.config.ConfigurableListableBeanFactory;
import org.springframework.context.EnvironmentAware;
import org.springframework.core.env.Environment;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Set;

/**
 * 状态后端配置的<b>早期明确拒绝</b>（配置选择与诊断；沿用 {@code ProvidersModeProductionGuard}
 * 的 {@link BeanFactoryPostProcessor} + {@link EnvironmentAware} 范式，先于常规单例实例化，
 * 因此一定抢在"缺 SessionProvider"这类注入失败之前给出真正原因）。
 *
 * <p><b>三条规则</b>：</p>
 * <ol>
 *   <li><b>非法取值 fail fast</b>：{@code app.state.provider} 既不是 {@code memory} 也不是
 *       {@code redis} ⇒ 拒绝启动。若不在此拦截，非法值会让两个装配门（{@code havingValue="memory"}
 *       与 {@code havingValue="redis"}）<b>都不匹配</b>，最终表现为难诊断的缺 bean 错误；</li>
 *   <li><b>选了 redis 却没给连接配置</b>：{@code spring.data.redis.url} / {@code host} /
 *       {@code sentinel.master} / {@code cluster.nodes} <b>都未显式设置</b> ⇒ 拒绝启动。
 *       判据用 {@link Environment#containsProperty(String)}（只检测<b>是否显式配置</b>，
 *       绝不读取值；Boot 的 {@code RedisProperties.host} 默认 {@code localhost} 是 Java 字段默认值
 *       而非属性源，因此未显式配置时 {@code containsProperty} 返回 false）。
 *       这条规则让"忘记配置 Redis"变成启动期的清晰诊断，而不是运行期一切请求 503；</li>
 *   <li><b>生产 + real 模式必须用 Redis</b>：出现生产信号（生效 profiles 含
 *       {@code prod}/{@code production}，或 {@code app.env} trim 后忽略大小写等于
 *       {@code production}）<b>且</b> {@code app.providers.mode} 归一后为 {@code real}
 *       <b>且</b> {@code app.state.provider != redis} ⇒ 拒绝启动。这把"联调/真实 provider
 *       使用 Redis"从约定变成<b>可执行的门禁</b>：进程内会话状态在生产意味着重启丢会话、
 *       多实例互相不认，属实质缺陷。</li>
 * </ol>
 *
 * <p><b>为什么规则 3 限定 {@code mode=real}</b>：生产 + {@code mode=doubles} 已由既有
 * {@code ProvidersModeProductionGuard} 明确拒绝（且多个既有测试锁定了它的异常与根因形态），
 * 本守卫不与之抢跑；生产 + {@code mode=disabled} 是"能力显式关闭 → 503"，
 * 此时会话能力本就不可用，状态后端选什么无关紧要，<b>不应</b>拒绝。</p>
 *
 * <p><b>消息纪律</b>：只输出键名、provider/mode 取值、生效 profiles 与 {@code app.env}；
 * 绝不输出 Redis 主机、端口、口令、数据库索引或任何凭据。</p>
 */
@Component
public class StateStoreConfigGuard implements BeanFactoryPostProcessor, EnvironmentAware {

    private static final Logger log = LoggerFactory.getLogger(StateStoreConfigGuard.class);

    /** 被视为"已显式给出连接配置"的标准 Spring Boot 属性（任一即可）。 */
    private static final List<String> CONNECTION_KEYS = List.of(
            "spring.data.redis.url",
            "spring.data.redis.host",
            "spring.data.redis.sentinel.master",
            "spring.data.redis.cluster.nodes");

    private Environment environment;

    @Override
    public void setEnvironment(Environment environment) {
        this.environment = environment;
    }

    @Override
    public void postProcessBeanFactory(ConfigurableListableBeanFactory beanFactory) throws BeansException {
        String rawProvider = environment.getProperty(AppStateProperties.PROVIDER_KEY);
        String provider;
        try {
            provider = AppStateProperties.normalizeProvider(rawProvider);
        } catch (IllegalArgumentException ex) {
            throw new IllegalStateException("state store fail-closed: " + ex.getMessage(), ex);
        }

        if (AppStateProperties.PROVIDER_REDIS.equals(provider)) {
            List<String> configured = CONNECTION_KEYS.stream()
                    .filter(key -> environment.containsProperty(key))
                    .toList();
            if (configured.isEmpty()) {
                String message = "state store fail-closed: " + AppStateProperties.PROVIDER_KEY
                        + "=redis requires an explicit Redis connection property, but none of "
                        + CONNECTION_KEYS + " is set (values are never logged);"
                        + " configure spring.data.redis.host (or .url / .sentinel.master / .cluster.nodes)"
                        + " together with spring.data.redis.password and spring.data.redis.database";
                log.error(message);
                throw new IllegalStateException(message);
            }
            return;
        }

        if (NonProductionCondition.isNonProduction(environment)) {
            return;
        }
        String mode = new AppProperties.Providers(environment.getProperty("app.providers.mode")).mode();
        if (!"real".equals(mode)) {
            return;
        }
        Set<String> profiles = NonProductionCondition.effectiveProfiles(environment);
        String appEnv = environment.getProperty("app.env", "dev");
        String message = "state store fail-closed: " + AppStateProperties.PROVIDER_KEY + "="
                + (rawProvider == null ? "<unset, defaults to memory>" : rawProvider.trim())
                + " is not allowed under production signals with app.providers.mode=real"
                + " (effective-profiles=" + profiles + ", app.env=" + appEnv + ");"
                + " in-process session/verification state does not survive restarts and is not"
                + " shared across instances - configure " + AppStateProperties.PROVIDER_KEY
                + "=redis with spring.data.redis.*";
        log.error(message);
        throw new IllegalStateException(message);
    }
}

